from typing import Literal, TypedDict

from app.additional_task_prompts import (
    DJANGO_TASK_PROMPTS,
    EXTRA_PYTHON_TASK_PROMPTS,
    FASTAPI_TASK_PROMPTS,
    REACT_TASK_PROMPTS,
    SingleIssueReviewTaskPrompt,
)
from app.models import Complexity, Issue, Severity, Task


class SimplePythonQuestionPrompt(TypedDict):
    slug: str
    title: str
    description: str
    code: str
    issue_line: int
    issue_title: str
    issue_description: str
    issue_suggestion: str
    issue_code: str


class PythonTheoryPrompt(TypedDict):
    title: str
    description: str
    question: str
    focus_points: list[str]
    expected_answer: str


def _simple_python_prompt(
    slug: str,
    title: str,
    description: str,
    code: str,
    issue_line: int,
    issue_title: str,
    issue_description: str,
    issue_suggestion: str,
    issue_code: str,
) -> SimplePythonQuestionPrompt:
    return {
        "slug": slug,
        "title": title,
        "description": description,
        "code": code,
        "issue_line": issue_line,
        "issue_title": issue_title,
        "issue_description": issue_description,
        "issue_suggestion": issue_suggestion,
        "issue_code": issue_code,
    }


def _python_theory_prompt(
    title: str,
    description: str,
    question: str,
    focus_points: list[str],
    expected_answer: str,
) -> PythonTheoryPrompt:
    return {
        "title": title,
        "description": description,
        "question": question,
        "focus_points": focus_points,
        "expected_answer": expected_answer,
    }


def _single_issue_prompt(
    title: str,
    description: str,
    code: str,
    issue_line: int,
    issue_title: str,
    issue_description: str,
    issue_suggestion: str,
    issue_code: str,
    issue_severity: Literal["critical", "medium", "low"] = "medium",
) -> SingleIssueReviewTaskPrompt:
    return {
        "title": title,
        "description": description,
        "code": code,
        "issue_line": issue_line,
        "issue_severity": issue_severity,
        "issue_title": issue_title,
        "issue_description": issue_description,
        "issue_suggestion": issue_suggestion,
        "issue_code": issue_code,
    }


