        "Precompute state from props once",
        "Builds a local options list from incoming items.",
        """import { useState } from \"react\";\n\nexport default function Options({ items }) {\n  const [options] = useState(items.map((item) => ({ label: item.name, value: item.id })));\n  return <div>{options.length}</div>;\n}\n""",
        4,
