def build_simple_python_question_task(
    index: int,
    prompt: SimplePythonQuestionPrompt,
    *,
    language: str = "python_questions",
    task_prefix: str = "python-question",
    issue_prefix: str = "python-question",
) -> Task:
    return Task(
        id=f"{task_prefix}-{index}",
        title=prompt["title"],
        description=prompt["description"],
        requirements=[
            "Spot the main bug",
            "Explain why it fails",
            "Suggest a small fix",
        ],
        instructions=[
            "Review the code",
            "Call out the main issue",
            "Suggest a corrected version",
        ],
        language=language,
        code=prompt["code"],
        reference_issues=[
            Issue(
                id=f"{issue_prefix}-{index}-i1",
                line=prompt["issue_line"],
                severity=Severity.medium,
                title=prompt["issue_title"],
                description=prompt["issue_description"],
                suggestion=prompt["issue_suggestion"],
                code=prompt["issue_code"],
            )
        ],
    )


def build_python_theory_task(index: int, prompt: PythonTheoryPrompt) -> Task:
    prompt_lines = "\n".join(f"# - {point}" for point in prompt["focus_points"])
    code = (
        "# Python theory question\n"
        f"# {prompt['question']}\n"
        "#\n"
        "# Include these points in your answer:\n"
        f"{prompt_lines}\n"
    )
    return Task(
        id=f"python-theory-{index}",
        title=prompt["title"],
        description=prompt["description"],
        requirements=[
            "Answer in 2-4 sentences",
            "Cover the core concept",
            "Use correct Python terminology",
        ],
        instructions=[
            "Read the prompt in the code viewer",
            "Write a concise answer in your own words",
            "Submit your answer for correctness analysis",
        ],
        language="python_theory",
        submission_mode="answer",
        code=code,
        reference_issues=[
            Issue(
                id=f"python-theory-{index}-i1",
                line=1,
                severity=Severity.medium,
                title=prompt["title"],
                description=prompt["expected_answer"],
                suggestion="Expected answer should cover: " + ", ".join(prompt["focus_points"]),
                code=prompt["expected_answer"],
            )
        ],
    )


SIMPLE_REVIEW_REQUIREMENTS = [
    "Spot the main bug",
    "Explain why it matters",
    "Suggest a targeted fix",
]


SIMPLE_REVIEW_INSTRUCTIONS = [
    "Review the code in the viewer",
    "Call out the main issue",
    "Suggest a corrected version",
]


def build_single_issue_review_task(
    *,
    task_id: str,
    language: str,
    prompt: SingleIssueReviewTaskPrompt,
) -> Task:
    return Task(
        id=task_id,
        title=prompt["title"],
        description=prompt["description"],
        requirements=SIMPLE_REVIEW_REQUIREMENTS,
        instructions=SIMPLE_REVIEW_INSTRUCTIONS,
        language=language,
        code=prompt["code"],
        reference_issues=[
            Issue(
                id=f"{task_id}-i1",
                line=prompt["issue_line"],
                severity=Severity(prompt["issue_severity"]),
                title=prompt["issue_title"],
                description=prompt["issue_description"],
                suggestion=prompt["issue_suggestion"],
                code=prompt["issue_code"],
            )
        ],
    )


def infer_task_complexity(task: Task) -> Complexity:
    score = 0
    code_line_count = len(task.code.splitlines())
    severity_score = sum(
        (
            2
            if issue.severity == Severity.critical
            else 1
            if issue.severity == Severity.medium
            else 0
        )
        for issue in task.reference_issues
    )

    score += severity_score
    score += max(0, len(task.requirements) - 3)

    if task.submission_mode == "answer":
        score -= 1

    if task.language in {
        "python_questions",
        "pandas",
        "asyncio",
        "graphql",
        "security",
    }:
        score -= 1
    elif task.language in {"machine_learning", "langchain_langgraph"}:
        score += 1
    elif task.language in {"fastapi", "django", "react", "sql", "javascript"}:
        score += 2

    if code_line_count >= 35:
        score += 2
    elif code_line_count >= 20:
        score += 1

    if score <= 1:
        return Complexity.easy
    if score <= 4:
        return Complexity.medium
    return Complexity.hard


