                severity=Severity.medium,
                title="Socket not reusable after restart",
                description="Without SO_REUSEADDR, restarting server gives 'Address already in use'.",
                suggestion="Set server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1).",
