    # == JS-7. Express middleware: Rate limiter ==
    Task(
        id="js-task-7",
        title="Express rate limiting middleware",
        description="Middleware that limits requests per IP using an in-memory counter.",
        requirements=[
            "Enforce rate limits correctly",
            "Handle time window expiration",
            "Avoid memory leaks",
            "Return proper status codes",
        ],
        instructions=[
            "Review the code",
            "Add inline comments",
            "Explain impact and risk",
            "Suggest improvements",
            "(Optional) Provide fixed code",
        ],
        language="javascript",
        code="const tracker = {};\n\nfunction rateLimiter(req, res, next) {\n  const ip = req.ip;\n  const now = Date.now();\n\n  if (!tracker[ip]) {\n    tracker[ip] = { count: 1, start: now };\n    return next();\n  }\n\n  const entry = tracker[ip];\n  if (now - entry.start > 60000) {\n    entry.count = 1;\n    entry.start = now;\n    return next();\n  }\n\n  entry.count++;\n  if (entry.count > 100) {\n    return res.json({ error: 'Rate limited' });\n  }\n\n  next();\n}\n\nmodule.exports = rateLimiter;\n",
        reference_issues=[
            Issue(
                id="js7-i1",
                line=1,
                severity=Severity.critical,
                title="Unbounded memory growth",
                description="tracker object grows forever; expired entries are never cleaned up.",
                suggestion="Periodically prune expired entries or use a Map with TTL.",
                code="// Prune expired entries\nfor (const [ip, entry] of Object.entries(tracker)) {\n  if (now - entry.start > 60000) delete tracker[ip];\n}",
            ),
            Issue(
                id="js7-i2",
                line=21,
                severity=Severity.critical,
                title="Rate limit response uses HTTP 200",
                description="Returns JSON error with 200 status instead of 429 Too Many Requests.",
                suggestion="Use res.status(429) for rate-limited responses.",
                code="return res.status(429).json({ error: 'Too many requests' });",
            ),
            Issue(
                id="js7-i3",
                line=19,
                severity=Severity.medium,
                title="Off-by-one: allows 101 requests",
                description="Increments count before checking, so the 101st request passes.",
                suggestion="Check before incrementing, or use >= instead of >.",
                code="if (entry.count >= 100) {\n  return res.status(429).json({ error: 'Too many requests' });\n}\nentry.count++;",
            ),
            Issue(
                id="js7-i4",
                line=4,
                severity=Severity.low,
                title="req.ip can be spoofed behind proxy",
                description="Without trust proxy, req.ip may not reflect the real client IP.",
                suggestion="Configure app.set('trust proxy', true) or use X-Forwarded-For header.",
            ),
        ],
    ),
    # == JS-8. Caching: In-memory LRU cache ==
    Task(
        id="js-task-8",
        title="In-memory LRU cache implementation",
        description="Simple LRU cache using a plain object to reduce repeated API calls.",
        requirements=[
            "Enforce max size",
            "Evict least-recently-used",
            "Handle edge cases",
            "Avoid memory leaks",
        ],
        instructions=[
            "Review the code",
            "Add inline comments",
            "Explain impact and risk",
            "Suggest improvements",
            "(Optional) Provide fixed code",
        ],
        language="javascript",
        code="class LRUCache {\n  constructor(maxSize = 100) {\n    this.maxSize = maxSize;\n    this.cache = {};\n    this.size = 0;\n  }\n\n  get(key) {\n    return this.cache[key];\n  }\n\n  set(key, value) {\n    if (this.size >= this.maxSize) {\n      const firstKey = Object.keys(this.cache)[0];\n      delete this.cache[firstKey];\n      this.size--;\n    }\n    this.cache[key] = value;\n    this.size++;\n  }\n\n  delete(key) {\n    delete this.cache[key];\n  }\n}\n\nmodule.exports = LRUCache;\n",
        reference_issues=[
            Issue(
                id="js8-i1",
                line=9,
                severity=Severity.critical,
                title="No access-order tracking",
                description="get() doesn't update recency; eviction removes oldest-inserted, not least-recently-used.",
                suggestion="Use a Map (which preserves insertion order) and re-insert on access.",
                code="get(key) {\n  if (!this.cache.has(key)) return undefined;\n  const value = this.cache.get(key);\n  this.cache.delete(key);\n  this.cache.set(key, value);\n  return value;\n}",
            ),
            Issue(
                id="js8-i2",
                line=18,
                severity=Severity.medium,
                title="Size tracking is wrong on overwrite",
                description="Setting an existing key increments size again without evicting.",
                suggestion="Check if key already exists before incrementing size.",
                code="set(key, value) {\n  if (key in this.cache) {\n    this.cache[key] = value;\n    return;\n  }\n  // ... eviction and insert\n}",
            ),
            Issue(
                id="js8-i3",
                line=23,
                severity=Severity.medium,
                title="delete() doesn't decrement size",
                description="Size counter becomes inaccurate after deleting entries.",
                suggestion="Decrement size when deleting an existing key.",
                code="delete(key) {\n  if (key in this.cache) {\n    delete this.cache[key];\n    this.size--;\n  }\n}",
            ),
            Issue(
                id="js8-i4",
                line=14,
                severity=Severity.low,
                title="Object key order is fragile",
                description="Object.keys()[0] relies on insertion order; use Map for guaranteed order.",
                suggestion="Replace plain object with Map for reliable insertion order.",
            ),
        ],
    ),
