        language="rust",
        code='use std::thread;\n\nstatic mut COUNTER: i32 = 0;\n\nfn increment() {\n    unsafe {\n        COUNTER += 1;\n    }\n}\n\nfn main() {\n    let mut handles = vec![];\n    for _ in 0..10 {\n        handles.push(thread::spawn(|| {\n            for _ in 0..1000 {\n                increment();\n            }\n        }));\n    }\n\n    for h in handles {\n        h.join();\n    }\n\n    unsafe {\n        println!("Counter: {}", COUNTER);\n    }\n}\n',
