                suggestion="Use AtomicI32 or Arc<Mutex<i32>> for thread-safe shared state.",
                code="use std::sync::atomic::{AtomicI32, Ordering};\nstatic COUNTER: AtomicI32 = AtomicI32::new(0);\n\nfn increment() {\n    COUNTER.fetch_add(1, Ordering::SeqCst);\n}",
