        code='use std::collections::HashMap;\nuse md5;\n\nstruct AuthStore {\n    users: HashMap<String, String>,\n}\n\nimpl AuthStore {\n    fn new() -> Self {\n        AuthStore { users: HashMap::new() }\n    }\n\n    fn register(&mut self, username: &str, password: &str) -> bool {\n        if self.users.contains_key(username) {\n            return false;\n        }\n        let hash = format!("{:x}", md5::compute(password));\n        self.users.insert(username.to_string(), hash);\n        true\n    }\n\n    fn login(&self, username: &str, password: &str) -> bool {\n        let hash = format!("{:x}", md5::compute(password));\n        match self.users.get(username) {\n            Some(stored) => stored == &hash,\n            None => false,\n        }\n    }\n}\n',
